sys_script_client.script:
function onLoad() {
    var cat = g_form.getValue('category');
    var subCat = g_form.getValue('subcategory');
    var inc = new GlideAjax('x_1921506_incide_0.AssignmentEngine');
    inc.addParam('sysparm_name', 'getAssignmentGroup');
    inc.addParam('sysparm_category', cat);
    inc.addParam('sysparm_sub', subCat);
	 g_form.addInfoMessage(' grp sys id');

    inc.getXMLAnswer(handleResponse);
}

function handleResponse(answer) {
    if (answer) {
  g_form.addInfoMessage(answer + ' grp sys id');
        // g_form.setValue('u_email_address', answer);
    }
}
